export function compactRequest(value){
  if(Array.isArray(value)){
    return value.map(compactRequest);
  }
  if(value && ((typeof value) == "object")){
    let pairs = [];
    for(let pair of Object.entries(value)){
      if(!(pair[1] === undefined)){
        pairs.push([pair[0],compactRequest(pair[1])]);
      }
    };
    return Object.fromEntries(pairs);
  }
  return value;
}

export function validate(schema,value,path = "input"){
  if(Array.isArray(schema.type)){
    let found = schema.type.some(function (type){
      try{
        validate(Object.assign({},schema,{"type":type}),value,path);
        return true;
      }
      catch(error){
        return false;
      }
    });
    if(!found){
      throw new Error("Invalid " + path);
    }
    return value;
  }
  let valid = true;
  if(schema.type == "null"){
    valid = (value === null);
  }
  else if(schema.type == "string"){
    valid = ((typeof value) == "string");
  }
  else if(schema.type == "boolean"){
    valid = ((typeof value) == "boolean");
  }
  else if((schema.type == "number") || (schema.type == "integer")){
    valid = (Number.isFinite(value) && ((schema.type == "number") || Number.isInteger(value)));
  }
  else if(schema.type == "array"){
    valid = Array.isArray(value);
  }
  else if(schema.type == "object"){
    valid = (value && ((typeof value) == "object") && !Array.isArray(value));
  }
  else{
    throw new Error("Unsupported account schema");
  }
  if(!valid){
    throw new Error("Invalid " + path);
  }
  if(schema.enum && !schema.enum.includes(value)){
    throw new Error("Invalid " + path);
  }
  if((schema.format == "uuid") && !new RegExp(
    "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$"
  ).test(value)){
    throw new Error("Invalid " + path);
  }
  if((schema.format == "date") && !new RegExp("^[0-9]{4}-[0-9]{2}-[0-9]{2}$").test(value)){
    throw new Error("Invalid " + path);
  }
  if(schema.type == "array"){
    value.forEach(function (item,index){
      validate(schema.items,item,path + "." + index);
    });
  }
  if(schema.type == "object"){
    (schema.required || []).forEach(function (key){
      if(!Object.prototype.hasOwnProperty.call(value,key)){
        throw new Error("Missing " + path + "." + key);
      }
    });
    Object.entries(value).forEach(function (pair){
      let key = pair[0];
      let child = (schema.properties || {})[key];
      if(!child && (schema.additionalProperties === false)){
        throw new Error("Unknown " + path + "." + key);
      }
      if(child){
        validate(child,pair[1],path + "." + key);
      }
    });
  }
  return value;
}